INSERT INTO public.genres (genre_id, genre_created_at, genre_updated_at, genre_color, genre_name, genre_type, genre_description) VALUES (38, '2025-07-25 23:38:36.054820', '2025-08-02 23:38:02.275837', '#220000', 'Atmospheric Black Metal', 0, 'Atmospheric Black Metal is a subgenre of black metal that blends the raw intensity and dark aesthetics of traditional black metal with ambient, ethereal, and often melodic soundscapes. It emphasizes mood and atmosphere, using elements like layered guitars, synths, and expansive song structures to evoke a sense of vastness, solitude, or mysticism.');
